package com.ryanjei.orushio.pve.map;import static org.junit.jupiter.api.Assertions.*;import com.ryanjei.orushio.pve.domain.MapProfileId;import java.util.*;import org.junit.jupiter.api.Test;
class MapSelectionServiceTest{@Test void zeroOneAndPreviousAvoidance(){MapSelectionService s=new MapSelectionService(new Random(1));assertThrows(IllegalStateException.class,()->s.select(List.of(),null));MapProfile a=MapProfileTest.complete("a").withEnabled(true),b=MapProfileTest.complete("b").withEnabled(true);assertEquals(a,s.select(List.of(a),null));assertEquals(b,s.select(List.of(a,b),a.mapId()));}@Test void fixedMapIsUsedOnceAndDisabledExcluded(){MapSelectionService s=new MapSelectionService(new Random(1));MapProfile a=MapProfileTest.complete("a").withEnabled(true),b=MapProfileTest.complete("b").withEnabled(true),off=MapProfileTest.complete("off");s.fixNext(b);assertEquals(b,s.select(List.of(a,b,off),null));assertTrue(s.fixedNext().isEmpty());assertNotEquals(off,s.select(List.of(a,off),null));}}
